              {
                "id": "block",
                "filter": "box",
                "options": {
                  "size": [
                    2,
                    2,
                    4
                  ],
                  "position": [
                    0,
                    1,
                    0
                  ]
                },
                "inputs": {
                  "material": "paint",
                  "parent": "arm"
                }
              },
              {
                "id": "arm",
                "filter": "transformGroup",
                "options": {
                  "position": [
                    1,
                    0,
                    0
                  ],
                  "rotation": [
                    0,
                    0,
                    45
                  ],
                  "scale": [
                    1,
                    3,
                    1
                  ]
                },
                "inputs": {
                  "parent": "assembly"
                }
              },
              {
                "id": "assembly",
                "filter": "transformGroup",
                "options": {
                  "position": [
                    10,
                    0,
                    0
                  ],
                  "rotation": [
                    0,
                    0,
                    90
                  ],
                  "scale": [
                    2,
                    1,
                    1
                  ]
                },
                "inputs": {
                  "parent": "arm"
                }
              },
              {
                "id": "empty",
                "filter": "transformGroup"
              },
              {
                "id": "view",
                "filter": "camera",
                "options": {
                  "position": [
                    15,
                    8,
                    20
                  ],
                  "target": [
                    8,
                    0,
                    0
                  ],
                  "orbit": false
                }
              },
              {
                "id": "sun",
                "filter": "directionalLight"
              }
            ]
